import{_ as r,C as o,o as n,c as l,j as i,E as s,a as e,a3 as d}from"./chunks/framework.C6R8kWFE.js";const v=JSON.parse(`{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/8-sinf-cs/"},"n":1,"bob":"I-bob · Kompyuter savodxonligi va arxitekturasi","lessons":[{"g":1,"title":"Zamonaviy kompyuterlar va ularning arxitekturasi","lead":"Har kuni foydalanadigan kompyuteringiz aslida qanday ishlaydi? Ushbu darsda kompyuterning «ichki dunyosi»ga sayohat qilamiz: protsessor, tezkor xotira, fon Neyman arxitekturasi va kompyuterning yashirin texnik parametrlarini ochishni o'rganamiz.","link":"/8-sinf-cs/hafta-01/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-1-test.html"},{"g":2,"title":"Operatsion tizimlar va Windows muhitida ishlash","lead":"Kompyuterni yoqqaningizda ekranda jilvalanadigan chiroyli ish stoli va derazalar ortida qanday kuch turibdi? Ushbu darsda kompyuterning «boshqaruvchi yuragi» bo'lgan operatsion tizimlar, Windows 10/11 imkoniyatlari, oynalarni bo'lish va dasturlarni professional boshqarishni o'rganamiz.","link":"/8-sinf-cs/hafta-01/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-2-test.html"},{"g":3,"title":"Axborot o‘lchov birliklari va fayl turlari. Windows operatsion tizimida fayl hamda papkalar yaratish. Tezkor tugmalar (Hot keys)","lead":"Nega kompyuterda 1 kilobayt 1000 emas, balki 1024 baytga teng? Har bir fayl ortida qanday kengaytma yashiringan va nima uchun professional dasturchilar sichqonchadan ko'ra tezkor tugmalarni (Hot keys) afzal ko'rishadi? Ushbu darsda axborot hisob-kitoblari va fayllarni boshqarish sirlarini o'rganamiz.","link":"/8-sinf-cs/hafta-01/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"8-sinf-cs/hafta-01/index.md","filePath":"8-sinf-cs/hafta-01/index.md"}`),h={name:"8-sinf-cs/hafta-01/index.md"},u={class:"blk"},c={id:"uyga-vazifa",tabindex:"-1"};function g(m,a,k,y,p,f){const t=o("Icon");return n(),l("div",null,[i("div",u,[i("h2",c,[s(t,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi.</p><h3 id="_1-dars-uchun-zamonaviy-kompyuterlar-va-ularning-arxitekturasi" tabindex="-1">1-dars uchun (Zamonaviy kompyuterlar va ularning arxitekturasi) <a class="header-anchor" href="#_1-dars-uchun-zamonaviy-kompyuterlar-va-ularning-arxitekturasi" aria-label="Permalink to &quot;1-dars uchun (Zamonaviy kompyuterlar va ularning arxitekturasi)&quot;">​</a></h3><p><strong>1-topshiriq: «Mening kompyuterim pasporti»</strong></p><ol><li>O&#39;zingiz foydalanadigan kompyuter (yoki maktab kompyuteri) turini aniqlang (Desktop PC, noutbuk yoki monoblok).</li><li><code>Ctrl + Shift + Esc</code> (Task Manager) yoki <code>Win + R</code> → <code>msinfo32</code> orqali protsessor (CPU) modeli va uning takt chastotasini yozing.</li><li>Operativ xotira (RAM) hajmini aniqlang.</li><li>Doimiy xotira diskining turi (SSD yoki HDD) va umumiy hajmini yozing.</li><li>Kompyuteringizga ulangan 2 ta kiritish va 2 ta chiqarish qurilmasi nomini daftaringizga qayd eting.</li></ol><p><strong>Kutiladigan natija:</strong> Kompyuterning barcha texnik parametrlari aniq ko&#39;rsatilgan qisqa «texnik pasport».</p><h3 id="_2-dars-uchun-operatsion-tizimlar-va-windows-muhitida-ishlash" tabindex="-1">2-dars uchun (Operatsion tizimlar va Windows muhitida ishlash) <a class="header-anchor" href="#_2-dars-uchun-operatsion-tizimlar-va-windows-muhitida-ishlash" aria-label="Permalink to &quot;2-dars uchun (Operatsion tizimlar va Windows muhitida ishlash)&quot;">​</a></h3><p><strong>2-topshiriq: «Windows sozlamalari va tezkor boshqaruv»</strong></p><ol><li>Klaviaturadagi <code>Win + I</code> tugmalarini bosib, Sozlamalar oynasini oching. Kompyuteringizdagi Windows versiyasi va nashrini (masalan, Windows 11 Pro) yozib oling.</li><li>Ikkita dasturni (masalan, brauzer va Bloknot) ochib, <code>Win + Chapga strelka</code> va <code>Win + O&#39;ngga strelka</code> orqali ularni ekranga 50/50 qilib yonma-yon joylashtiring.</li><li>Klaviaturadagi <code>Alt + Tab</code>, <code>Win + D</code>, <code>Win + E</code> tugmalarini kamida 3 marta sinab ko&#39;ring va ularning har biri qanday natija berganini daftaringizga 1 jumlada yozing.</li><li><code>Settings</code> → «Installed apps» bo&#39;limiga kirib, kompyuteringizdagi 3 ta eng katta hajmli dasturning nomi va hajmini (MB yoki GB) yozing.</li></ol><p><strong>Kutiladigan natija:</strong> Windows tezkor tugmalari bo&#39;yicha amaliy tajriba va o&#39;rnatilgan dasturlar tahlili.</p><h3 id="_3-dars-uchun-axborot-o-lchov-birliklari-fayl-turlari-va-tezkor-tugmalar" tabindex="-1">3-dars uchun (Axborot o‘lchov birliklari, fayl turlari va tezkor tugmalar) <a class="header-anchor" href="#_3-dars-uchun-axborot-o-lchov-birliklari-fayl-turlari-va-tezkor-tugmalar" aria-label="Permalink to &quot;3-dars uchun (Axborot o‘lchov birliklari, fayl turlari va tezkor tugmalar)&quot;">​</a></h3><p><strong>3-topshiriq: «Axborot hisobi va papkalar daraxti»</strong></p><ol><li>Quyidagi axborot hisob-kitobini daftaringizda bajaring: <ul><li>$8 \\text{ GB}$ hajmli fleshkaga har biri $4 \\text{ MB}$ bo&#39;lgan qo&#39;shiqlardan nechta sig&#39;adi? ($8 \\text{ GB} = 8 \\times 1024 \\text{ MB}$).</li></ul></li><li>Kompyuteringizning <code>Documents</code> papkasida <code>CS_Foundation</code> nomli papka oching (<code>Ctrl + Shift + N</code>).</li><li>Uning ichida <code>Hujjatlar</code> va <code>Rasmlar</code> nomli ikkita ichki papka yarating.</li><li><code>Hujjatlar</code> ichida <code>reja.txt</code> faylini yarating, <code>Ctrl+C</code> va <code>Ctrl+V</code> orqali nusxasini oling, so&#39;ngra nusxasini <code>F2</code> bilan <code>reja_nusxa.txt</code> deb o&#39;zgartiring.</li><li><code>reja_nusxa.txt</code> faylini <code>Delete</code> bilan Savatchaga tashlang va Savatchadan «Restore» amali orqali qayta tiklab ko&#39;ring.</li></ol><p><strong>Kutiladigan natija:</strong> To&#39;g&#39;ri matematik hisoblash va kompyuterda yaratilgan tartibli papkalar strukturasi.</p>',13))])])}const z=r(h,[["render",g]]);export{v as __pageData,z as default};
